mapper.select:
SELECT * FROM coupon_template

    AND status = #{status}

ORDER BY id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT 
FROM user_coupon c JOIN coupon_template t ON t.id = c.template_id
WHERE c.id = #{id}

SELECT 
FROM user_coupon c JOIN coupon_template t ON t.id = c.template_id
WHERE c.template_id = #{templateId} AND c.user_id = #{userId}

SELECT 
FROM user_coupon c JOIN coupon_template t ON t.id = c.template_id
WHERE c.user_id = #{userId}
AND c.status = #{status}
ORDER BY CASE c.status WHEN 'UNUSED' THEN 0 WHEN 'USED' THEN 1 ELSE 2 END, c.expire_at
LIMIT #{limit} OFFSET #{offset}

SELECT count(*) FROM user_coupon c
WHERE c.user_id = #{userId}
AND c.status = #{status}

SELECT r.*, t.name AS template_name
FROM redeem_code r JOIN coupon_template t ON t.id = r.template_id
WHERE r.code = #{code}

SELECT r.*, t.name AS template_name, u.real_name AS used_by_name FROM redeem_code r JOIN coupon_template t ON t.id = r.template_id LEFT JOIN sys_user u ON u.id = r.used_by
AND r.status = #{status}
ORDER BY r.id DESC LIMIT #{limit} OFFSET #{offset}
